/**
 * The native command manifest, the capability allow-list, and the generated
 * permission files must agree.
 *
 * `build.rs` is what generates `permissions/autogenerated/`, and the native
 * build runs from a mirror outside this checkout (see scripts/native-mirror.sh,
 * because iCloud breaks tauri-build in place). Generated files therefore land in
 * the mirror, so a command added to `capabilities/default.json` without a
 * matching `build.rs` entry builds locally and fails on a clean checkout. This
 * test is the only place that notices, and it needs no Rust toolchain.
 */
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { describe, it } from "node:test";

const TAURI = path.join(import.meta.dirname, "..", "..", "app", "src-tauri");

function manifestCommands() {
  const src = fs.readFileSync(path.join(TAURI, "build.rs"), "utf8");
  const block = /\.commands\(&\[([\s\S]*?)\]\)/.exec(src);
  assert.ok(block, "build.rs no longer declares commands(&[...])");
  return new Set([...block[1].matchAll(/"([a-z0-9_]+)"/g)].map((m) => m[1]));
}

function capabilityCommands() {
  const caps = JSON.parse(fs.readFileSync(path.join(TAURI, "capabilities", "default.json"), "utf8"));
  return new Set(
    caps.permissions
      .filter((p) => typeof p === "string" && p.startsWith("allow-"))
      .map((p) => p.slice("allow-".length).replaceAll("-", "_")),
  );
}

function generatedCommands() {
  const dir = path.join(TAURI, "permissions", "autogenerated");
  return new Set(fs.readdirSync(dir).filter((f) => f.endsWith(".toml")).map((f) => f.slice(0, -".toml".length)));
}

describe("tauri command manifest", () => {
  const manifest = manifestCommands();
  const caps = capabilityCommands();
  const generated = generatedCommands();

  it("allows no capability for a command build.rs does not declare", () => {
    // This is the failure that breaks a clean checkout: the permission the
    // capability names is never generated, so the ACL will not resolve.
    assert.deepEqual([...caps].filter((c) => !manifest.has(c)).sort(), []);
  });

  it("has a committed permission file for every declared command", () => {
    assert.deepEqual([...manifest].filter((c) => !generated.has(c)).sort(), []);
  });

  it("has no permission file for a command that no longer exists", () => {
    assert.deepEqual([...generated].filter((c) => !manifest.has(c)).sort(), []);
  });

  it("registers every declared command in the invoke handler", () => {
    const main = fs.readFileSync(path.join(TAURI, "src", "main.rs"), "utf8");
    const block = /generate_handler!\[([\s\S]*?)\]/.exec(main);
    assert.ok(block, "main.rs no longer uses generate_handler![...]");
    // Entries are bare or module-qualified; the command is the last segment.
    const handlers = new Set(
      block[1]
        .split(",")
        .map((entry) => entry.trim().split("::").pop())
        .filter((name) => /^[a-z0-9_]+$/.test(name)),
    );
    assert.deepEqual([...manifest].filter((c) => !handlers.has(c)).sort(), []);
  });
});
